for g in glob.glob(home+'/DEV/*/.git')+glob.glob(home+'/DEV/*/*/.git'):
    repos[os.path.basename(os.path.dirname(g)).lower()]=os.path.dirname(g)
rows=[]
for p in d['projects']:
