    if df: keys|={df.lower(), df.lower().replace('_',' '), df.lower().replace('_','-')}
    keys={k for k in keys if len(k)>3}
    days=[dt for dt,t in logs.items() if any(k in t for k in keys)]
    hits=sum(sum(t.count(k) for k in keys) for t in logs.values())
    path=repos.get((df or name).lower())
    commits=0
    if path:
        r=subprocess.run(['git','-C',path,'log','--since=2026-10-01','--oneline'],capture_output=True,text=True)
        commits=len(r.stdout.splitlines())
