        if in_next and not heading and nxt is None:
            item = BULLET.sub("", line, count=1).strip()
            if item and item not in ("—", "-") and not item.startswith("~~"):   # ~~struck~~ = done
                nxt = _clean(item)
        if section.startswith(NOT_PROGRESS) and not (heading and DATED.match(line)):
            continue
        m = DATED.match(line)
        if m and (stands_date is None or m.group(1) >= stands_date):   # last one wins a tie
            stands_date, stands = m.group(1), _clean(m.group(2))
    return {"stands": stands, "stands_date": stands_date, "next": nxt}


def _when(e: dict) -> _dt.datetime:
    try:
        return _dt.datetime.fromisoformat(e["when"])
    except (KeyError, ValueError):
        return _dt.datetime.min.replace(tzinfo=_dt.timezone.utc)


def last_touched(registry: dict, ledger: list[dict]) -> dict[str, dict]:
    """project name -> newest ledger entry for it."""
    idx = landed.project_index(registry)
    best: dict[str, dict] = {}
    for e in ledger:
        name = landed.project_for(e, idx)
        if name not in best or _when(e) > _when(best[name]):
            best[name] = e
    return best


def touched_since(registry: dict, ledger: list[dict], since: str) -> list[str]:
    """Registry projects with a ledger entry at or after `since` (ISO), newest first.

    Paths that map to no row ("(DEV) X") are left to crosswalk, which owns unregistered folders.
    """
    idx = landed.project_index(registry)
    names = {p["name"] for p in registry.get("projects", [])}
    cutoff = _when({"when": since})
    newest: dict[str, _dt.datetime] = {}
    for e in ledger:
        name, when = landed.project_for(e, idx), _when(e)
        if name in names and when >= cutoff and (name not in newest or when > newest[name]):
            newest[name] = when
    return sorted(newest, key=newest.get, reverse=True)


def status_date(dev_root: Path, row: dict) -> str | None:
    """Date of the newest entry in a project's STATUS.md, or None."""
    if not row.get("dev_folder"):
        return None
    try:
        text = (Path(dev_root) / row["dev_folder"] / "docs" / "STATUS.md").read_text(
            encoding="utf-8", errors="ignore")
    except OSError:
        return None
    return parse_status(text)["stands_date"]


def card_gaps(row: dict, card: dict | None, today: str, said_on: str | None = None) -> list[str]:
    """What keeps a touched project's card from being true (PM design Decision 9). [] = fine.
    said_on: newest STATUS date of a retired row; an entry dated today is the "why it was touched"."""
    if row.get("status") in ARCHIVED:
        if said_on == today:
            return []
        return [f"touched but marked {row['status']}: revive it, or say why it was touched"]
    card = card or {}
    gaps = []
    if row.get("dev_folder"):
        if card.get("stands_from") != "status" or card.get("stands_date") != today:
            gaps.append(f"STATUS has no entry dated {today}")
        if card.get("next_from") != "status":
            gaps.append("STATUS has no Next item")
    elif not card.get("next"):
        gaps.append("no next step (next_action)")
    if card.get("receiver_needed"):
        gaps.append("needs a receiver")
    return gaps


def format_card(row: dict, card: dict | None, gaps: list[str]) -> str:
    """The resume card as closeout prints it: what / stands / next / touched, then gaps."""
    card = card or {}
    head = f"{row['name']}  [{row.get('lane')} · {row.get('status')}"
    head += f" · for {card['receiver']}]" if card.get("receiver") else "]"
    stands = f"{card['stands_date']} {card['stands']}" if card.get("stands") else "nothing on record"
    touched = (f"{card['touched'][:16].replace('T', ' ')} ({card.get('touched_on') or '?'})"
               if card.get("touched") else "not in the ledger")
    return "\n".join([
        head,
        f"  what:    {row.get('purpose') or 'no purpose yet'}",
        f"  stands:  {stands}",
        f"  next:    {card.get('next') or 'none'}",
        f"  touched: {touched}",
        f"  gaps:    {'; '.join(gaps) if gaps else 'none'}",
    ])


def next_due(charter: dict | None) -> tuple[str | None, str | None]:
    """(date, what) of the earliest undone charter step, else finish_by; the board's hard date."""
    if not charter:
        return None, None
    open_steps = sorted((s["due"], s.get("name", "step")) for s in charter.get("steps", [])
                        if s.get("due") and not s.get("done") and not s.get("skipped"))
    if open_steps:
        return open_steps[0]
    return (charter["finish_by"], "finish by") if charter.get("finish_by") else (None, None)


def build_cards(registry: dict, dev_root: Path, ledger: list[dict],
                today: _dt.date | None = None) -> dict[str, dict]:
    """Resume card per live project (retired rows get none)."""
    today = today or _dt.date.today()
    touched = last_touched(registry, ledger)
    out = {}
    for p in registry.get("projects", []):
        if p.get("status") in ARCHIVED:
            continue
        parsed = {"stands": None, "stands_date": None, "next": None}
        if p.get("dev_folder"):
            try:
                text = (Path(dev_root) / p["dev_folder"] / "docs" / "STATUS.md").read_text(
                    encoding="utf-8", errors="ignore")
                parsed = parse_status(text)
            except OSError:
                pass
        card = dict(parsed, next_from="status" if parsed["next"] else None,
                    stands_from="status" if parsed["stands"] else None)
        if not card["next"] and (p.get("next_action") or "").strip():
            card["next"], card["next_from"] = _clean(p["next_action"]), "registry"
        if not card["stands"] and p.get("updates"):
            card["stands_date"], card["stands"] = p["updates"][0].get("date"), _clean(p["updates"][0].get("note", ""))
            card["stands_from"] = "registry"
        card["due"], card["due_what"] = next_due(p.get("charter"))
        card["receiver"], card["receiver_needed"] = portfolio.receiver_of(p), portfolio.receiver_needed(p)
        card["clock_left"] = seven_day.days_left(p, today)             # 7-day rule countdown
        card["clock_needs"] = seven_day.missing(p) if card["clock_left"] is not None else None
        e = touched.get(p["name"])
        card["touched"] = e["when"] if e else None
        card["touched_on"] = e.get("machine") if e else None
        out[p["name"]] = card
    return out

