  if(document.hidden || !REG || polling) return;
  polling = true;
  try {
    const names = REG.projects.filter(p => p.lane === lane)
      .map(p => encodeURIComponent(p.name)).join(",");
    const {sig} = await api("/api/changes?names=" + names);
    if(lastSig !== null && sig !== lastSig) await reloadIfIdle();
    lastSig = sig;
  } catch(e){ /* board stopped or restarting: stay quiet, try next tick */ }
  finally { polling = false; }
}
