"""dates and drift: the Front Burner's self-checks (plan 2026-10-31, Phase 1 steps 4-5)."""
import datetime
import tempfile
import unittest
from pathlib import Path

import frontburner
import portfolio

TODAY = datetime.date(2026, 10, 31)


def row(name, status="active", lane="job", **extra):
    return {"name": name, "lane": lane, "rank": 1, "status": status,
            "purpose": "", "next_action": "", **extra}


def charter(*steps):
    return {"steps": [dict(name=n, due=d, done=done) for n, d, done in steps]}


class TestDates(unittest.TestCase):
    def test_every_overdue_step_on_every_active_row_is_listed_touched_or_not(self):
        data = {"projects": [
            row("A", charter=charter(("Plan agreed with receiver", "2026-10-02", None),
                                     ("First draft to receiver", "2026-10-09", None),
                                     ("Final delivered", "2026-11-20", None))),
            row("B", charter=charter(("Plan agreed with receiver", "2026-10-30", None))),
            row("P", status="paused", charter=charter(("Final delivered", "2026-10-01", None))),
        ]}
        got = frontburner.dates(data, TODAY)
        self.assertEqual([(i["project"], i["kind"]) for i in got],
                         [("A", "overdue"), ("A", "overdue"), ("B", "overdue")])
        self.assertTrue(all(i["needs_eric"] for i in got))

    def test_done_and_future_steps_are_fine(self):
        data = {"projects": [row("A", charter=charter(("Plan", "2026-10-02", "2026-10-03"),
                                                      ("Final", "2026-11-20", None)))]}
        self.assertEqual(frontburner.dates(data, TODAY), [])

    def test_a_row_with_neither_a_date_nor_no_hard_date_is_listed(self):
        data = {"projects": [row("A")]}
        self.assertEqual([i["kind"] for i in frontburner.dates(data, TODAY)], ["no_date"])

    def test_no_hard_date_clears_it_until_30_days_old(self):
        fresh = row("A", no_hard_date={"reason": "weekly capture", "source": "STATUS",
                                       "set_on": "2026-10-20"})
        old = row("B", no_hard_date={"reason": "waits on Mauro", "source": "STATUS",
                                     "set_on": "2026-09-01"})
        got = frontburner.dates({"projects": [fresh, old]}, TODAY)
        self.assertEqual([(i["project"], i["kind"]) for i in got], [("B", "stale_no_hard_date")])

    def test_finish_by_counts_as_a_date(self):
        data = {"projects": [row("A", charter={"finish_by": "2026-12-01", "steps": []})]}
        self.assertEqual(frontburner.dates(data, TODAY), [])


class TestNoHardDateValidation(unittest.TestCase):
    def base(self, **extra):
        return {"meta": {}, "ideas": [], "projects": [row("A", **extra)]}

    def test_a_complete_record_passes(self):
        portfolio.validate(self.base(no_hard_date={"reason": "r", "source": "s", "set_on": "2026-10-31"}))

    def test_missing_fields_or_bad_date_fail(self):
        for bad in ({"reason": "r"}, {"reason": "", "source": "s", "set_on": "2026-10-31"},
                    {"reason": "r", "source": "s", "set_on": "10/31"}, "weekly"):
            with self.subTest(bad=bad), self.assertRaises(portfolio.RegistryError):
                portfolio.validate(self.base(no_hard_date=bad))


class FakeGit:
    """Stands in for `git`: per-folder log dates, status output, or a failure."""

    def __init__(self, log=None, status=None, fail=None):
        self.log, self.status, self.fail = log or {}, status or {}, fail or {}

    def __call__(self, folder: Path, args: list[str]):
        key = (folder.name, args[0])
        if key in self.fail:
            return False, "", self.fail[key]
        if args[0] == "log":
            return True, "\n".join(self.log.get(folder.name, [])), ""
        return True, self.status.get(folder.name, ""), ""


class TestDrift(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)

    def tearDown(self):
        self.tmp.cleanup()

    def repo(self, name):
        (self.root / name / ".git").mkdir(parents=True)
        return name

    def plain(self, name):
        (self.root / name).mkdir(parents=True)
        return name

    def run_drift(self, projects, git, ledger=()):
        return frontburner.drift({"projects": projects}, self.root, list(ledger), TODAY, 14, git)

    def kinds(self, report):
        return {(i["project"], i["kind"]) for i in report["items"]}

    def test_active_repo_with_no_commits_and_clean_tree_is_quiet(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"))], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "quiet")})
        self.assertTrue(rep["items"][0]["needs_eric"])

    def test_uncommitted_changes_make_it_touched_not_quiet(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"))],
                             FakeGit(status={"A": " M analysis.py"}))
        self.assertEqual(rep["states"]["A"]["state"], "touched")
        self.assertEqual(self.kinds(rep), set())

    def test_a_failed_git_command_is_unknown_never_quiet(self):
        for cmd in ("log", "status"):
            with self.subTest(cmd=cmd):
                rep = self.run_drift([row("A", dev_folder=self.repo("A"))],
                                     FakeGit(fail={("A", cmd): "fatal: bad object"}))
                self.assertEqual(self.kinds(rep), {("A", "cant_track")})
                self.assertIn("git " + cmd, rep["items"][0]["message"])

    def test_git_plus_drive_folder_says_drive_not_confirmed(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"), drive_folder="X/A")], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "quiet")})
        self.assertIn("Drive not confirmed", rep["items"][0]["message"])

    def test_ledger_only_evidence_is_never_quiet(self):
        rep = self.run_drift([row("A", drive_folder="X/A")], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "cant_track")})
        self.assertIn("scan coverage unknown", rep["items"][0]["message"])

    def test_cant_track_reasons(self):
        rep = self.run_drift([row("NoFolder"), row("Gone", dev_folder="Gone"),
                              row("Plain", dev_folder=self.plain("Plain"))], FakeGit())
        msgs = {i["project"]: i["message"] for i in rep["items"]}
        self.assertIn("no folder mapped", msgs["NoFolder"])
        self.assertIn("folder missing", msgs["Gone"])
        self.assertIn("not a git repo", msgs["Plain"])
        self.assertFalse(any(i["needs_eric"] for i in rep["items"]))

    def test_off_board_work_needs_two_commit_days(self):
        rep = self.run_drift(
            [row("W", status="archived", dev_folder=self.repo("W")),
             row("T", status="paused", dev_folder=self.repo("T")),
             row("S", status="archived", lane="system", dev_folder=self.repo("S"))],
            FakeGit(log={"W": ["2026-10-29", "2026-10-30"], "T": ["2026-10-30"],
                         "S": ["2026-10-29", "2026-10-30"]}))
        self.assertEqual(self.kinds(rep), {("W", "off_board"), ("T", "off_board_weak")})
        need = {i["project"]: i["needs_eric"] for i in rep["items"]}
        self.assertEqual(need, {"W": True, "T": False})

    def test_status_only_ledger_entries_are_not_work(self):
        ledger = [{"root": "DEV", "path": "A/docs/STATUS.md", "when": "2026-10-30T10:00:00-05:00"}]
        rep = self.run_drift([row("A", dev_folder=self.plain("A"))], FakeGit(), ledger)
        self.assertEqual(rep["states"]["A"]["state"], "unknown")

    def test_ledger_entry_inside_the_window_is_touched(self):
        ledger = [{"root": "DEV", "path": "A/report.R", "when": "2026-10-30T10:00:00-05:00"}]
        rep = self.run_drift([row("A", dev_folder=self.plain("A"))], FakeGit(), ledger)
        self.assertEqual(rep["states"]["A"]["state"], "touched")

    def test_cap_warning_above_ten_active(self):
        rows = [row(f"P{i}", dev_folder=self.repo(f"P{i}")) for i in range(11)]
        rep = self.run_drift(rows, FakeGit(log={f"P{i}": ["2026-10-29", "2026-10-30"] for i in range(11)}))
        self.assertEqual([i["kind"] for i in rep["items"]], ["cap"])

    def test_report_text_ends_lines_with_the_fixing_command(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"))], FakeGit())
        text = frontburner.format_drift(rep)
        self.assertIn("/project park A", text)


if __name__ == "__main__":
    unittest.main()

