// ---------- Today strip: every active row, one list, soonest date first ----------
// Order: overdue, then by due date, then rows with no hard date (lane order, then rank).
// Front Burner plan 2026-10-31, Phase 1 step 2. Text is set as text nodes, never HTML.
function todayRows(){
  const rows = REG.projects.filter(p => p.status === "active").map(p => {
    const c = (REG.cards && REG.cards[p.name]) || {};
    return {p, c, due: c.due || null};
  });
  const key = r => [r.due ? 0 : 1, r.due || "", LANES.indexOf(r.p.lane), r.p.rank || 1e6];
  return rows.sort((a, b) => {
    const ka = key(a), kb = key(b);
    for(let i = 0; i < ka.length; i++) if(ka[i] !== kb[i]) return ka[i] < kb[i] ? -1 : 1;
    return 0;
  });
}
function todayStrip(){
  const sec = document.createElement("section"); sec.className = "today";
  const h = document.createElement("h2");
  const rows = todayRows();
  h.textContent = `Today · ${rows.length} on the board`;
  sec.append(h);
  const ol = document.createElement("ol");
  rows.forEach(({p, c, due}) => {
    const li = document.createElement("li");
    const overdue = due && due < REG.today;
    if(overdue) li.className = "late";
    const d = document.createElement("span"); d.className = "when";
    d.textContent = due ? (overdue ? "overdue " : "") + due.slice(5).replace("-", "/") : "no hard date";
    if(due && c.due_what) d.title = c.due_what;
    else if(p.no_hard_date) d.title = p.no_hard_date.reason;
    const n = document.createElement("button"); n.className = "plain nm";
    n.append(nameNodes(p.name));
    n.title = `Open the ${p.lane} lane`;
    n.onclick = () => { lane = p.lane; openCard = p.name; render(); };
    const nx = document.createElement("span"); nx.className = "nx";
    nx.textContent = c.next || p.next_action || "no next step";
