def _since_for(p: dict, since: _dt.date) -> _dt.date:
    """Window start for one row. A "keep it off the board" answer is stored as the Friday
    sweep stores "keep": parked_until = decision day + sweep.KEEP_DAYS. Only work after that
    decision counts, so new work re-surfaces and old work is not asked about again (FB-5)."""
    until = _date(p.get("parked_until"))
    if not until or p.get("status") == "active":
        return since
    decided = until - _dt.timedelta(days=PARK_DAYS)
    return max(since, decided + _dt.timedelta(days=1))


