1	#!/usr/bin/env node
2	// SessionStart hook: inject the Tier B global memory snapshot (USER.md,
3	// MEMORY.md, and .errors.log when non-empty) plus KeystoneOS's cross-harness
4	// unified snapshot, alongside the memory compiler's own snapshot.
5	//
6	// This replaces the prose instruction in ~/.claude/CLAUDE.md that told the
7	// agent to read those three files by hand at session start — a rule nothing
8	// enforced, which therefore silently did not happen in some sessions.
9	//
10	// Fails closed: any error means less context, never a thrown error that could
11	// block session start. But a MISSING SOURCE IS REPORTED, not swallowed — the
12	// old version pointed at the retired ~/Desktop/DEV path and injected nothing
13	// at all for weeks without a single visible symptom (see project memory
14	// `memsearch-index-path-drift`: make fallbacks loud).
15	
16	const fs = require('fs');
17	const path = require('path');
18	const os = require('os');
19	
20	const HOME = os.homedir();
21	
22	const SOURCES = [
23	  {
24	    label: 'User profile (global-memory/USER.md)',
25	    file: path.join(HOME, '.claude', 'global-memory', 'USER.md'),
26	    required: true,
27	  },
28	  {
29	    label: 'Working memory (global-memory/MEMORY.md)',
30	    file: path.join(HOME, '.claude', 'global-memory', 'MEMORY.md'),
31	    required: true,
32	  },
33	  {
34	    label: 'HOOK FAILURES — surface these to the user on the first response',
35	    file: path.join(HOME, '.claude', 'global-memory', 'transcripts', '.errors.log'),
36	    required: false,      // absent is fine
37	    skipIfEmpty: true,    // normally empty; only inject when it is not
38	    summarize: true,      // one line per failure kind, not one per occurrence
39	  },
40	  {
41	    // Points, does not paste: ~6k chars of recent activity that most sessions
42	    // never need. Recorded decision — see project memory
43	    // `memory-compiler-pipeline`: "SessionStart now points, not pastes".
44	    // Flip `pointOnly` to false to inline it again.
45	    label: 'Cross-harness activity (KeystoneOS unified snapshot)',
46	    // Mac: ~/DEV. Windows: ~/Desktop/DEV. First path that exists wins.
47	    file: [path.join(HOME, 'DEV'), path.join(HOME, 'Desktop', 'DEV')]
48	      .map((d) => path.join(d, 'KeystoneOS', 'outputs', 'dashboard', 'unified-snapshot.md'))
49	      .find((f) => fs.existsSync(f)) || path.join(HOME, 'DEV', 'KeystoneOS', 'outputs', 'dashboard', 'unified-snapshot.md'),
50	    required: false,
51	    pointOnly: true,
52	  },
53	];
54	
55	// .errors.log lines look like `[ISO-time] kind: message`. A stuck job writes
56	// the same kind every few minutes, so the raw log can reach 100+ near-identical
57	// lines injected into every session. Collapse to one line per kind: count,
58	// first and last time, and the latest message (which carries the running count).
59	function summarizeErrors(body) {
60	  const groups = new Map();
61	  const other = [];
62	  for (const line of body.split(/\r?\n/)) {
63	    const m = line.match(/^\[([^\]]+)\]\s*([\w.-]+):\s*(.*)$/);
64	    if (!m) { if (line.trim()) other.push(line.trim()); continue; }
65	    const [, ts, kind, msg] = m;
66	    const g = groups.get(kind) || { n: 0, first: ts, last: ts, msg };
67	    // Both machines append, so lines are not in time order: track min/max.
68	    g.n += 1;
69	    if (ts < g.first) g.first = ts;
70	    if (ts >= g.last) { g.last = ts; g.msg = msg; }
71	    groups.set(kind, g);
72	  }
73	  const t = (s) => s.slice(0, 16).replace('T', ' ');
74	  const cap = (s) => (s.length > 300 ? s.slice(0, 300) + '…' : s);
75	  const lines = [...groups].map(([kind, g]) =>
76	    `- **${kind}** ×${g.n} (${t(g.first)} → ${t(g.last)} UTC): ${cap(g.msg)}`);
77	  if (other.length) lines.push(`- ${other.length} unparsed line(s); see the file.`);
78	  return lines.join('\n') +
79	    `\n\nFull log: \`~/.claude/global-memory/transcripts/.errors.log\`. ` +
80	    'Surface this once; clear the file after the user has seen it and the cause is handled.';
81	}
82	
83	function emit(context) {
84	  if (process.argv.includes('--agy')) {
85	    const out = context
86	      ? { injectSteps: [{ systemMessage: { systemMessage: context } }] }
87	      : {};
88	    process.stdout.write(JSON.stringify(out));
89	    return;
90	  }
91	  const output = { hookSpecificOutput: { hookEventName: 'SessionStart' } };
92	  if (context) output.hookSpecificOutput.additionalContext = context;
93	  process.stdout.write(JSON.stringify(output));
94	}
95	
96	function main() {
97	  const parts = [];
98	  const problems = [];
99	
100	  for (const src of SOURCES) {
101	    let body;
102	    try {
103	      body = fs.readFileSync(src.file, 'utf8');
104	    } catch (err) {
105	      if (src.required) {
106	        problems.push(`${src.label}: unreadable at ${src.file} (${err.code || 'ERR'})`);
107	      }
108	      continue;
109	    }
110	    if (src.skipIfEmpty && body.trim() === '') continue;
111	    if (src.pointOnly) {
112	      const stamp = fs.statSync(src.file).mtime.toISOString().slice(0, 16).replace('T', ' ');
113	      parts.push(
114	        `## ${src.label}\n\nNot loaded here — read it only if a question needs it.\n` +
115	        `Path: \`${src.file}\` (${body.length} chars, updated ${stamp})`
116	      );
117	      continue;
118	    }
119	    parts.push(`## ${src.label}\n\n${src.summarize ? summarizeErrors(body) : body.trim()}`);
120	  }
121	
122	  // Dead-man check: the weekly stack doctor reports failures through .errors.log,
123	  // so a run that never happens reports nothing (missed 10-26 unseen). Mac only:
124	  // the laptop has no weekly run. 8 days = one missed Monday.
125	  if (process.platform === 'darwin') {
126	    const weekly = process.env.STACKDOCTOR_WEEKLY_LOG ||
127	      path.join(HOME, '.claude', 'skills', 'claude-stack-doctor', 'scripts', 'last-weekly-run.log');
128	    let ageD = Infinity;
129	    try { ageD = (Date.now() - fs.statSync(weekly).mtimeMs) / 86400000; } catch (_) {}
130	    if (ageD > 8) {
131	      parts.unshift(
132	        '## Weekly stack doctor is overdue\n\n' +
133	        `\`${weekly}\` is ${ageD === Infinity ? 'missing or unreadable' : Math.floor(ageD) + ' days old'}; ` +
134	        'the Monday launchd job `com.keystone.stackdoctor` did not run. Tell the user on the first ' +
135	        'response and run `/claude-stack-doctor`.'
136	      );
137	    }
138	  }
139	
140	  if (problems.length) {
141	    parts.unshift(
142	      '## SessionStart hook could not read a required memory file\n\n' +
143	      problems.map((p) => `- ${p}`).join('\n') +
144	      '\n\nTell the user on the first response. Do not work around it silently.'
145	    );
146	  }
147	
148	  emit(parts.length ? parts.join('\n\n---\n\n') : null);
149	}
150	
151	try {
152	  main();
153	} catch (_) {
154	  emit(null);
155	}
