    skipIfEmpty: true,    // normally empty; only inject when it is not
    summarize: true,      // one line per failure kind, not one per occurrence
  },
  {
    // Points, does not paste: ~6k chars of recent activity that most sessions
    // never need. Recorded decision — see project memory
    // `memory-compiler-pipeline`: "SessionStart now points, not pastes".
    // Flip `pointOnly` to false to inline it again.
    label: 'Cross-harness activity (KeystoneOS unified snapshot)',
    // Mac: ~/DEV. Windows: ~/Desktop/DEV. First path that exists wins.
    file: [path.join(HOME, 'DEV'), path.join(HOME, 'Desktop', 'DEV')]
      .map((d) => path.join(d, 'KeystoneOS', 'outputs', 'dashboard', 'unified-snapshot.md'))
      .find((f) => fs.existsSync(f)) || path.join(HOME, 'DEV', 'KeystoneOS', 'outputs', 'dashboard', 'unified-snapshot.md'),
    required: false,
    pointOnly: true,
  },
];

// .errors.log lines look like `[ISO-time] kind: message`. A stuck job writes
// the same kind every few minutes, so the raw log can reach 100+ near-identical
// lines injected into every session. Collapse to one line per kind: count,
// first and last time, and the latest message (which carries the running count).
function summarizeErrors(body) {
  const groups = new Map();
  const other = [];
  for (const line of body.split(/\r?\n/)) {
    const m = line.match(/^\[([^\]]+)\]\s*([\w.-]+):\s*(.*)$/);
    if (!m) { if (line.trim()) other.push(line.trim()); continue; }
    const [, ts, kind, msg] = m;
    const g = groups.get(kind) || { n: 0, first: ts, last: ts, msg };
    // Both machines append, so lines are not in time order: track min/max.
    g.n += 1;
    if (ts < g.first) g.first = ts;
    if (ts >= g.last) { g.last = ts; g.msg = msg; }
    groups.set(kind, g);
  }
  const t = (s) => s.slice(0, 16).replace('T', ' ');
  const cap = (s) => (s.length > 300 ? s.slice(0, 300) + '…' : s);
  const lines = [...groups].map(([kind, g]) =>
    `- **${kind}** ×${g.n} (${t(g.first)} → ${t(g.last)} UTC): ${cap(g.msg)}`);
  if (other.length) lines.push(`- ${other.length} unparsed line(s); see the file.`);
  return lines.join('\n') +
    `\n\nFull log: \`~/.claude/global-memory/transcripts/.errors.log\`. ` +
    'Surface this once; clear the file after the user has seen it and the cause is handled.';
}

function emit(context) {
  if (process.argv.includes('--agy')) {
    const out = context
      ? { injectSteps: [{ systemMessage: { systemMessage: context } }] }
      : {};
    process.stdout.write(JSON.stringify(out));
    return;
  }
  const output = { hookSpecificOutput: { hookEventName: 'SessionStart' } };
  if (context) output.hookSpecificOutput.additionalContext = context;
  process.stdout.write(JSON.stringify(output));
}

function main() {
  const parts = [];
  const problems = [];

  for (const src of SOURCES) {
    let body;
    try {
      body = fs.readFileSync(src.file, 'utf8');
    } catch (err) {
      if (src.required) {
        problems.push(`${src.label}: unreadable at ${src.file} (${err.code || 'ERR'})`);
      }
      continue;
    }
    if (src.skipIfEmpty && body.trim() === '') continue;
    if (src.pointOnly) {
      const stamp = fs.statSync(src.file).mtime.toISOString().slice(0, 16).replace('T', ' ');
      parts.push(
        `## ${src.label}\n\nNot loaded here — read it only if a question needs it.\n` +
        `Path: \`${src.file}\` (${body.length} chars, updated ${stamp})`
      );
      continue;
    }
    parts.push(`## ${src.label}\n\n${src.summarize ? summarizeErrors(body) : body.trim()}`);
  }

  // Dead-man check: the weekly stack doctor reports failures through .errors.log,
  // so a run that never happens reports nothing (missed 10-26 unseen). Mac only:
  // the laptop has no weekly run. 8 days = one missed Monday.
  if (process.platform === 'darwin') {
    const weekly = process.env.STACKDOCTOR_WEEKLY_LOG ||
      path.join(HOME, '.claude', 'skills', 'claude-stack-doctor', 'scripts', 'last-weekly-run.log');
    let ageD = Infinity;
    try { ageD = (Date.now() - fs.statSync(weekly).mtimeMs) / 86400000; } catch (_) {}
    if (ageD > 8) {
      parts.unshift(
        '## Weekly stack doctor is overdue\n\n' +
        `\`${weekly}\` is ${ageD === Infinity ? 'missing or unreadable' : Math.floor(ageD) + ' days old'}; ` +
        'the Monday launchd job `com.keystone.stackdoctor` did not run. Tell the user on the first ' +
        'response and run `/claude-stack-doctor`.'
      );
    }
  }

  if (problems.length) {
    parts.unshift(
      '## SessionStart hook could not read a required memory file\n\n' +
      problems.map((p) => `- ${p}`).join('\n') +
      '\n\nTell the user on the first response. Do not work around it silently.'
    );
  }

  emit(parts.length ? parts.join('\n\n---\n\n') : null);
}

try {
  main();
} catch (_) {
  emit(null);
}

def classify(p: dict, dev_root: Path, ledger_day: str | None, since: _dt.date, git) -> dict:
    """{state, ...}: worked (git days >= 2) | touched | quiet | unknown (with reason)."""
    folder = Path(dev_root) / p["dev_folder"] if p.get("dev_folder") else None
    is_repo = bool(folder and (folder / ".git").exists())
    active = p.get("status") == "active"
    if is_repo:
        ev = _git_evidence(folder, since, check_status=active, git=git)
        if not ev["ok"]:          # a failed inspection is reported, never masked (FB-2)
            return {"state": "unknown", "reason": ev["error"]}
        days = ev["days"]
        if len(days) >= 2:
            return {"state": "worked", "days": len(days)}
        if len(days) == 1 or ev["dirty"] or ledger_day:
            how = ("uncommitted changes" if ev["dirty"] else
                   f"last changed {ledger_day}, day count unknown" if not days else "1 commit day")
            return {"state": "touched", "days": len(days), "how": how}
        if p.get("drive_folder"):
            return {"state": "quiet", "partial": True}
        return {"state": "quiet"}
    if ledger_day:
        return {"state": "touched", "how": f"last changed {ledger_day}, day count unknown"}
    if not folder and not p.get("drive_folder"):
        reason = "no folder mapped (no dev_folder or drive_folder)"
    elif folder and not folder.exists():
        reason = f"folder missing: {p['dev_folder']}"
    elif folder:
        reason = "not a git repo and no ledger entries"
    else:
        reason = "Drive-only: no activity seen; scan coverage unknown"
    return {"state": "unknown", "reason": reason}


def drift(data: dict, dev_root: Path, ledger: list[dict], today: _dt.date,
          days: int = 14, git=run_git) -> dict:
    days = max(1, min(days, landed.KEEP_DAYS))       # the ledger holds 30 days, no more
    since = today - _dt.timedelta(days=days)
    # Every non-active, non-system row except merged ones (absorbed into a parent) (FB-6).
    rows = [p for p in data.get("projects", [])
            if p.get("status") == "active"
            or (p.get("status") in ("paused", "archived", "done", "dropped") and p.get("lane") != "system")]
    row_since = {p["name"]: _since_for(p, since) for p in rows}
    lasts = {s: _ledger_last(data, ledger, s) for s in set(row_since.values())}
    with ThreadPoolExecutor(max_workers=8) as pool:
        states = dict(zip([p["name"] for p in rows], pool.map(
            lambda p: classify(p, dev_root, lasts[row_since[p["name"]]].get(p["name"]),
                               row_since[p["name"]], git), rows)))
    items = []
    active = [p for p in rows if p.get("status") == "active"]
    for p in active:
        s, n = states[p["name"]], p["name"]
        # mapping health is checked on its own, so Drive activity cannot hide a broken DEV path (FB-3)
        if p.get("dev_folder") and not (Path(dev_root) / p["dev_folder"]).exists() and s["state"] != "unknown":
            items.append(_item(n, "cant_track", False, f"can't track: folder missing: {p['dev_folder']}",
                               "fix dev_folder"))
        # "keep it on the board" is stored as quiet_ok_until = decision day + KEEP_QUIET_DAYS;
        # until then the quiet question is not asked again (inspection FB-8).
        if s["state"] == "quiet" and (p.get("quiet_ok_until") or "") > today.isoformat():
            continue
        if s["state"] == "quiet":
            msg =(f"no DEV commits in {days}d; Drive not confirmed" if s.get("partial")
                   else f"on the board, no work in {days}d")
            items.append(_item(n, "quiet", True, msg + ": keep it or park it?", f"/project park {n}"))
        elif s["state"] == "unknown":
            items.append(_item(n, "cant_track", False, f"can't track: {s['reason']}",
                               "map dev_folder or drive_folder"))
    for p in rows:
        if p.get("status") == "active":
            continue
        s, n = states[p["name"]], p["name"]
        if s["state"] == "worked":
            items.append(_item(n, "off_board", True,
                               f"real work, not on the board ({s['days']} commit days in {days}d): start it?",
                               f"/project start {n}"))
        elif s["state"] == "touched":
            items.append(_item(n, "off_board_weak", False,
                               f"changed recently, not on the board ({s['how']})", f"/project start {n}"))
    if len(active) > CAP:
        items.append(_item("(board)", "cap", False, f"{len(active)} active, cap {CAP}",
                           "answer the park questions"))
    return {"days": days, "since": since.isoformat(), "states": states, "items": items}


def format_drift(report: dict) -> str:
    items = report["items"]
    lines = [f"drift: {len(items)} item{'s' if len(items) != 1 else ''} (last {report['days']} days)"]
    lines += [f"  {i['kind']:<15} {i['project']}: {i['message']} -> {i['command']}" for i in items]
    return "\n".join(lines)


def _since_for(p: dict, since: _dt.date) -> _dt.date:
    """Window start for one row. A "keep it off the board" answer is stored as the Friday
    sweep stores "keep": parked_until = decision day + sweep.KEEP_DAYS. Only work after that
    decision counts, so new work re-surfaces and old work is not asked about again (FB-5)."""
    until = _date(p.get("parked_until"))
    if not until or p.get("status") == "active":
        return since
    decided = until - _dt.timedelta(days=PARK_DAYS)
    return max(since, decided + _dt.timedelta(days=1))


# ---------- helpers ----------

def _item(project, kind, needs_eric, message, command):
    return {"project": project, "kind": kind, "needs_eric": needs_eric,
            "message": message, "command": command}


def _date(value):
    try:
        return _dt.date.fromisoformat(value)
    except (TypeError, ValueError):
        return None

