            # (inspection FB-12); it is named so the answer can keep or drop it.
            fb = f" (finish_by {charter['finish_by']} only)" if charter.get("finish_by") else ""
            items.append(_item(name, "no_date", True,
                               f"no open dated step and no no_hard_date record{fb}: what is the next date?",
                               f"portfolio.py decide {name} redate|no-date", due=charter.get("finish_by") or ""))
        elif not open_steps and isinstance(nhd, dict):
            set_on = _date(nhd.get("set_on"))
            if set_on and (today - set_on).days > STALE_DAYS:
                items.append(_item(name, "stale_no_hard_date", True,
                                   f"'no hard date' ({nhd.get('reason')}) set {set_on}: still true?",
                                   f"portfolio.py decide {name} no-date (re-confirms)", due=""))
    return items


def format_dates(items: list[dict]) -> str:
    lines = [f"dates: {len(items)} item{'s' if len(items) != 1 else ''} on active rows"]
    lines += [f"  {i['kind']:<20} {i['project']}: {i['message']}" for i in items]
    return "\n".join(lines)


