from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import landed

ARCHIVED = {"done", "dropped", "merged", "archived"}
CAP = 10                      # soft cap: a warning, never a refusal
STALE_DAYS = 30               # a no_hard_date record is re-asked after this
GIT_TIMEOUT = 10
NOT_WORK = "docs/STATUS.md"   # closeout sweeps touch STATUS files everywhere; that is not work
PARK_DAYS = 90                # = sweep.KEEP_DAYS (not imported: sweep pulls in board_ops); test pins it
KEEP_QUIET_DAYS = 14          # a "keep it" answer to a quiet active row holds this long
LANE_ORDER = ["job", "side", "system", "knowledge", "tool"]   # board.html LANES order
TODAY_ROWS, CLIP = 8, 90
ALL_CMD = "python3 ~/DEV/project-triage/portfolio.py today --all"


# ---------- dates ----------

def dates(data: dict, today: _dt.date) -> list[dict]:
    items = []
    for p in data.get("projects", []):
        if p.get("status") != "active":
            continue
        name = p["name"]
        charter = p.get("charter") or {}
        steps = charter.get("steps") or []
        open_steps = [(i, s) for i, s in enumerate(steps, 1)
                      if s.get("due") and not s.get("done") and not s.get("skipped")]
        for i, s in sorted(open_steps, key=lambda t: t[1]["due"]):
            if s["due"] < today.isoformat():
                items.append(_item(name, "overdue", True,
                                   f"step {i} '{s.get('name', 'step')}' was due {s['due']}: done, new date, or no hard date?",
                                   f"portfolio.py decide {name} done|redate|no-date --step {i}", due=s["due"]))
        nhd = p.get("no_hard_date")
        if not open_steps and not nhd:
            # A2: an open dated step or a no_hard_date record. finish_by alone is not enough
            # (inspection FB-12); it is named so the answer can keep or drop it.
            fb = f" (finish_by {charter['finish_by']} only)" if charter.get("finish_by") else ""
            items.append(_item(name, "no_date", True,
                               f"no open dated step and no no_hard_date record{fb}: what is the next date?",
                               f"portfolio.py decide {name} redate|no-date", due=charter.get("finish_by") or ""))
        elif not open_steps and isinstance(nhd, dict):
            set_on = _date(nhd.get("set_on"))
            if set_on and (today - set_on).days > STALE_DAYS:
                items.append(_item(name, "stale_no_hard_date", True,
                                   f"'no hard date' ({nhd.get('reason')}) set {set_on}: still true?",
                                   f"portfolio.py decide {name} no-date (re-confirms)", due=""))
    return items


def format_dates(items: list[dict]) -> str:
    lines = [f"dates: {len(items)} item{'s' if len(items) != 1 else ''} on active rows"]
    lines += [f"  {i['kind']:<20} {i['project']}: {i['message']}" for i in items]
    return "\n".join(lines)


# ---------- drift ----------

def run_git(folder: Path, args: list[str]) -> tuple[bool, str, str]:
    """(ok, stdout, error). A timeout or a missing git binary is a failure, never "no output"."""
    try:
        r = subprocess.run(["git", "-C", str(folder), *args], capture_output=True, text=True,
                           timeout=GIT_TIMEOUT)
    except (OSError, subprocess.TimeoutExpired) as e:
        return False, "", f"{type(e).__name__}: {e}"
    first_err = (r.stderr.strip().splitlines() or [f"exit {r.returncode}"])[0]
    return r.returncode == 0, r.stdout, first_err if r.returncode else ""


def _git_evidence(folder: Path, since: _dt.datetime, check_status: bool, git) -> dict:
    # --since takes the exact timestamp, so work after a same-day decision counts (FB-11)
    ok, out, err = git(folder, ["log", f"--since={since.isoformat()}", "--format=%ad",
                                "--date=short", "--", ".", f":!{NOT_WORK}"])
    if not ok:
        return {"ok": False, "error": f"git log failed: {err}"}
    first = since.date().isoformat()
    days = sorted({d.strip() for d in out.splitlines() if d.strip() and d.strip() >= first})
    dirty = False
    if check_status:
        ok, out, err = git(folder, ["status", "--porcelain", "--", ".", f":!{NOT_WORK}"])
        if not ok:
            return {"ok": False, "error": f"git status failed: {err}", "days": days}
        dirty = bool(out.strip())
    return {"ok": True, "days": days, "dirty": dirty}


def _ledger_last(registry: dict, ledger: list[dict], since: _dt.datetime) -> dict[str, str]:
    """project -> newest non-STATUS ledger date at or after `since`."""
    idx = landed.project_index(registry)
    best: dict[str, str] = {}
    for e in ledger:
        if e.get("path", "").endswith(NOT_WORK):
            continue
        when = _when(e.get("when"))
        if when is None or when < since:
            continue
        name, day = landed.project_for(e, idx), when.date().isoformat()
        if day > best.get(name, ""):
            best[name] = day
    return best


def classify(p: dict, dev_root: Path, ledger_day: str | None, since: _dt.datetime, git) -> dict:
    """{state, ...}: worked (git days >= 2) | touched | quiet | unknown (with reason)."""
    folder = Path(dev_root) / p["dev_folder"] if p.get("dev_folder") else None
    is_repo = bool(folder and (folder / ".git").exists())
    active = p.get("status") == "active"
    if is_repo:
        ev = _git_evidence(folder, since, check_status=active, git=git)
        if not ev["ok"]:          # a failed inspection is reported, never masked (FB-2)
            return {"state": "unknown", "reason": ev["error"]}
        days = ev["days"]
        if len(days) >= 2:
            return {"state": "worked", "days": len(days)}
        if len(days) == 1 or ev["dirty"] or ledger_day:
            how = ("uncommitted changes" if ev["dirty"] else
                   f"last changed {ledger_day}, day count unknown" if not days else "1 commit day")
            return {"state": "touched", "days": len(days), "how": how}
        if p.get("drive_folder"):
            return {"state": "quiet", "partial": True}
        return {"state": "quiet"}
    if ledger_day:
        return {"state": "touched", "how": f"last changed {ledger_day}, day count unknown"}
    if not folder and not p.get("drive_folder"):
        reason = "no folder mapped (no dev_folder or drive_folder)"
    elif folder and not folder.exists():
        reason = f"folder missing: {p['dev_folder']}"
    elif folder:
        reason = "not a git repo and no ledger entries"
    else:
        reason = "Drive-only: no activity seen; scan coverage unknown"
    return {"state": "unknown", "reason": reason}


def _since_for(p: dict, window: _dt.datetime) -> _dt.datetime:
    """Window start for one row: only work after Eric last declined to start it counts.

    `drift_reviewed_at` (set by `decide keep-off`) is the exact moment (FB-11). Rows the Friday
    sweep kept carry only parked_until = decision day + PARK_DAYS; for those the whole decision
    day counts as new, which errs toward asking rather than hiding work."""
    if p.get("status") == "active":
        return window
    marks = [window]
    reviewed = _when(p.get("drift_reviewed_at"))
    if reviewed:
        marks.append(reviewed)
    until = _date(p.get("parked_until"))
    if until:
        decided = until - _dt.timedelta(days=PARK_DAYS)
        marks.append(_dt.datetime.combine(decided, _dt.time(), tzinfo=window.tzinfo))
    return max(marks)


def drift(data: dict, dev_root: Path, ledger: list[dict], today: _dt.date,
          days: int = 14, git=run_git) -> dict:
    days = max(1, min(days, landed.KEEP_DAYS))       # the ledger holds 30 days, no more
    tz = _dt.datetime.now().astimezone().tzinfo
    window = _dt.datetime.combine(today - _dt.timedelta(days=days), _dt.time(), tzinfo=tz)
    # Every non-active, non-system row except merged ones (absorbed into a parent) (FB-6).
    rows = [p for p in data.get("projects", [])
            if p.get("status") == "active"
            or (p.get("status") in ("paused", "archived", "done", "dropped") and p.get("lane") != "system")]
    row_since = {p["name"]: _since_for(p, window) for p in rows}
    lasts = {s: _ledger_last(data, ledger, s) for s in set(row_since.values())}
    with ThreadPoolExecutor(max_workers=8) as pool:
        states = dict(zip([p["name"] for p in rows], pool.map(
            lambda p: classify(p, dev_root, lasts[row_since[p["name"]]].get(p["name"]),
                               row_since[p["name"]], git), rows)))
    items = []
    active = [p for p in rows if p.get("status") == "active"]
    for p in active:
        s, n = states[p["name"]], p["name"]
        # mapping health is checked on its own, so Drive activity cannot hide a broken DEV path (FB-3)
        if p.get("dev_folder") and not (Path(dev_root) / p["dev_folder"]).exists() and s["state"] != "unknown":
            items.append(_item(n, "cant_track", False, f"can't track: folder missing: {p['dev_folder']}",
                               "fix dev_folder"))
        # "keep it on the board" is stored as quiet_ok_until (FB-8); not asked again until then
        if s["state"] == "quiet" and (p.get("quiet_ok_until") or "") > today.isoformat():
            continue
        if s["state"] == "quiet":
            msg = (f"no DEV commits in {days}d; Drive not confirmed" if s.get("partial")
                   else f"on the board, no work in {days}d")
            items.append(_item(n, "quiet", True, msg + ": keep it or park it?",
                               f"portfolio.py decide {n} keep-quiet | /project park {n}"))
        elif s["state"] == "unknown":
            items.append(_item(n, "cant_track", False, f"can't track: {s['reason']}",
                               "map dev_folder or drive_folder"))
    for p in rows:
        if p.get("status") == "active":
            continue
        s, n = states[p["name"]], p["name"]
        if s["state"] == "worked":
            items.append(_item(n, "off_board", True,
                               f"real work, not on the board ({s['days']} commit days in {days}d): start it?",
                               f"/project start {n} | portfolio.py decide {n} keep-off"))
        elif s["state"] == "touched":
            items.append(_item(n, "off_board_weak", False,
                               f"changed recently, not on the board ({s['how']})", f"/project start {n}"))
    if len(active) > CAP:
        items.append(_item("(board)", "cap", False, f"{len(active)} active, cap {CAP}",
                           "answer the park questions"))
    return {"days": days, "since": window.date().isoformat(), "states": states, "items": items}


def format_drift(report: dict) -> str:
    items = report["items"]
    lines = [f"drift: {len(items)} item{'s' if len(items) != 1 else ''} (last {report['days']} days)"]
    lines += [f"  {i['kind']:<15} {i['project']}: {i['message']} -> {i['command']}" for i in items]
    return "\n".join(lines)


# ---------- decide: record one closeout answer ----------

DECISIONS = ("done", "redate", "no-date", "keep-quiet", "keep-off")


def decide(data: dict, name: str, action: str, today: _dt.date, *, step: int | None = None,
           date: str | None = None, reason: str = "", source: str = "",
           now: _dt.datetime | None = None) -> str:
    """Apply one answer so `dates` / `drift` stop asking it. Raises ValueError on bad input."""
    row = next((p for p in data.get("projects", []) if p["name"] == name), None)
    if row is None:
        raise ValueError(f"no project named '{name}'")
    if action not in DECISIONS:
        raise ValueError(f"action must be one of {DECISIONS}")
    t = today.isoformat()
    charter = row.get("charter") or {}
    steps = charter.get("steps") or []

    def pick() -> dict:
        if step is None or not 1 <= step <= len(steps):
            raise ValueError(f"{name}: --step must be 1-{len(steps)}")
        return steps[step - 1]

    if action == "done":
        s = pick()
        s["done"] = date or t
        msg = f"step {step} '{s.get('name')}' done {s['done']}"
    elif action == "redate":
        if not date or _date(date) is None or _date(date).isoformat() != date:
            raise ValueError("redate needs --date YYYY-MM-DD")
        if step is None:
            row.setdefault("charter", {}).setdefault("steps", []).append(
                {"name": "Next date", "due": date, "done": None})
            row.pop("no_hard_date", None)
            msg = f"new step 'Next date' due {date}"
        else:
            s = pick()
            s["due"] = date
            msg = f"step {step} '{s.get('name')}' re-dated to {date}"
    elif action == "no-date":
        if not reason.strip() or not source.strip():
            raise ValueError("no-date needs --reason and --source")
        targets = [pick()] if step is not None else [s for s in steps if s.get("due") and not s.get("done")]
        for s in targets:
            if not s.get("done"):
                s["skipped"] = {"date": t, "reason": reason.strip()}
        # with no open dated step left, an old finish_by would come back as the board's date (FB-10)
        if charter.get("finish_by") and not any(
                s.get("due") and not s.get("done") and not s.get("skipped") for s in steps):
            charter.pop("finish_by")
        row["no_hard_date"] = {"reason": reason.strip(), "source": source.strip(), "set_on": t}
        msg = f"no hard date: {reason.strip()} ({source.strip()})"
    elif action == "keep-quiet":
        row["quiet_ok_until"] = (today + _dt.timedelta(days=KEEP_QUIET_DAYS)).isoformat()
        msg = f"kept on the board while quiet; not asked again before {row['quiet_ok_until']}"
    else:  # keep-off
        stamp = (now or _dt.datetime.now().astimezone()).isoformat(timespec="seconds")
        row["drift_reviewed_at"] = stamp
        msg = f"left off the board; only work after {stamp} is asked about"
    row.setdefault("updates", []).insert(0, {"date": t, "note": f"[decide] {msg}"})
    return f"{name}: {msg}"


# ---------- today: the session-start block ----------

def _today_order(data: dict, cards_map: dict) -> list[dict]:
    """Active rows, overdue first, then by date, then no date (lane order, rank): board.html's order."""
    rows = [p for p in data.get("projects", []) if p.get("status") == "active"]

    def key(p):
        due = (cards_map.get(p["name"]) or {}).get("due")
        lane = LANE_ORDER.index(p["lane"]) if p.get("lane") in LANE_ORDER else 99
        return (0 if due else 1, due or "", lane, p.get("rank") or 10**6)
    return sorted(rows, key=key)


def today_block(data: dict, cards_map: dict, date_items: list[dict], drift_items: list[dict],
                today: _dt.date, show_all: bool = False) -> str:
    """At most 15 lines: heading, <=8 Today rows, a count line, one attention line per non-empty
    category (its first item in queue order), and an overflow line when anything was cut."""
    rows = _today_order(data, cards_map)
    cats = {
        "dates": [i for i in date_items if i["needs_eric"]],
        "can't track": [i for i in drift_items if i["kind"] == "cant_track"],
        "quiet": [i for i in drift_items if i["kind"] == "quiet"],
        "off the board": [i for i in drift_items if i["kind"] == "off_board"],
    }
    cats["dates"].sort(key=lambda i: (i.get("due") or "9999", i["project"]))
    rank = {p["name"]: (p.get("rank") or 10**6) for p in data.get("projects", [])}
    for k in ("can't track", "quiet", "off the board"):
        cats[k].sort(key=lambda i: (rank.get(i["project"], 10**6), i["project"]))
    cap = next((i for i in drift_items if i["kind"] == "cap"), None)
    head = f"## Front Burner ({len(rows)} active{', cap 10' if cap else ''}; board: /project)"
    lines = [head]
    shown = rows if show_all else rows[:TODAY_ROWS]
    t = today.isoformat()
    for p in shown:
        c = cards_map.get(p["name"]) or {}
        due = c.get("due")
        when = (("OVERDUE " if due < t else "") + due[5:].replace("-", "/")) if due else "no date"
        nxt = (c.get("next") or p.get("next_action") or "no next step").strip()
        if not show_all and len(nxt) > CLIP:
            nxt = nxt[:CLIP - 1].rstrip() + "…"
        lines.append(f"- {when} · {p['name']}: {nxt}")
    counts = [f"{len(v)} {k}" for k, v in cats.items() if v]
    lines.append("Waiting: " + (" · ".join(counts) if counts else "nothing"))
    cut = len(rows) > len(shown)
    for k, v in cats.items():
        for i in (v if show_all else v[:1]):
            lines.append(f"- [{k}] {i['project']}: {i['message']} -> {i['command']}")
        cut = cut or (len(v) > 1 and not show_all)
    if show_all:
        lines += [f"- [{i['kind']}] {i['project']}: {i['message']}" for i in drift_items
                  if i["kind"] in ("off_board_weak",)]
    elif cut:
        lines.append(f"All: `{ALL_CMD}`")
    return "\n".join(lines)


# ---------- helpers ----------

def _item(project, kind, needs_eric, message, command, due=""):
    return {"project": project, "kind": kind, "needs_eric": needs_eric,
            "message": message, "command": command, "due": due}


def _date(value):
    try:
        return _dt.date.fromisoformat(value)
    except (TypeError, ValueError):
        return None


def _when(value):
    """Aware datetime from an ISO string; naive values are taken as local time."""
    try:
        d = _dt.datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None
    return d if d.tzinfo else d.astimezone()

