# --- slate: job-lane prioritization rules ------------------------------------
# Design: DEV/project-triage/docs/superpowers/specs/2026-09-14-prioritization-system-design.md
# Every earlier prioritization fix (5/22 note, 6/2 brief, 6/12 tracker, 7/31 note)
# died because it had to be remembered. The rules are evaluated in project-triage;
# this only puts the verdict somewhere unavoidable.
#
# Not age-based either: the signal is the rule state today (over cap, a dated step
# missed, a checkpoint missed, a charter missing a receiver). And a check that
# FAILS must not read as OK - a silent pass is the invisible absence this script
# was written to catch.
$slateStatus = "DUE"
$slateWhy = ""
try {
    $slateArgs = @($PortfolioScript, "slate-check", "--json", "--today", $today.ToString('yyyy-MM-dd'))
    if ($SlateRegistry) { $slateArgs += @("--registry", $SlateRegistry) }
    $raw = & $Python @slateArgs 2>&1 | Out-String
    if ($LASTEXITCODE -ne 0) { throw "slate-check exited $LASTEXITCODE - $($raw.Trim())" }
    $slate = $raw | ConvertFrom-Json
    $slateStatus = $slate.status
    $slateWhy = if (-not $slate.enabled) {
                    "slate not configured in portfolio.json (meta.slate missing)"
                } elseif (@($slate.problems).Count -eq 0) {
                    "$($slate.active) of $($slate.cap) active, every step on date"
                } else {
                    (@($slate.problems) | Select-Object -First 3 | ForEach-Object { "$($_.project): $($_.message)" }) -join " | "
                }
}
catch {
    $slateWhy = "slate check could not run: $_"
}
# Friday: write Eric's weekly slate report into the vault. Both Friday runs
# (15:30 and 17:00) overwrite the same dated file, so the later one includes the
# afternoon's debrief. A report he has to remember to run is the failure this
# system replaces, so the timer writes it.
if ($today.DayOfWeek -eq 'Friday') {
    try {
        $weekArgs = @($PortfolioScript, "week-report", "--end", $today.ToString('yyyy-MM-dd'),
                      "--out", (Join-Path $Vault "Inbox/weekly-slate"))
        if ($SlateRegistry) { $weekArgs += @("--registry", $SlateRegistry) }
        $wout = & $Python @weekArgs 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0) { throw "week-report exited $LASTEXITCODE - $($wout.Trim())" }
        $slateWhy += " | weekly report: Inbox/weekly-slate/$($today.ToString('yyyy-MM-dd')).md"
    }
    catch {
        if ($slateStatus -eq "OK") { $slateStatus = "DUE" }
        $slateWhy += " | weekly report could not be written: $_"
    }
}
$rituals += [pscustomobject]@{
