"""Friday report: what moved on the active job projects in the 7 days ending `end`.

Written by KeystoneOS/scripts/ritual-check.ps1 on Fridays into the vault
(Inbox/weekly-slate/<end>.md; the folder keeps its old name so existing notes stay together).
It was part of slate.py until the slate retired (design Decision 11, 2026-10-30); the
Front Burner plan (2026-10-31, Phase 4) moved it here and kept only the "moves" view.
"""
from __future__ import annotations

import datetime as _dt


def _date(value):
    try:
        return _dt.date.fromisoformat(value)
    except (TypeError, ValueError):
        return None


def week_report(data: dict, end: _dt.date) -> str:
    start = end - _dt.timedelta(days=6)
    lines = [f"# Weekly moves - week ending {end}", f"Window: {start} to {end}", "",
             "What moved on active job projects:", ""]
    active = sorted((p for p in data.get("projects", [])
                     if p.get("lane") == "job" and p.get("status") == "active"),
                    key=lambda p: p.get("rank", 0))
    for p in active:
        updates = sorted((u for u in p.get("updates") or []
                          if (d := _date(u.get("date"))) and start <= d <= end),
                         key=lambda u: u["date"])
        lines += [f"## {p['name']}", ""]
        lines += [f"- {u['date']}: {u['note']}" for u in updates] or ["- No movement logged this week."]
        lines.append("")
    return "\n".join(lines)

