p = "scripts/ritual-check.ps1"; s = open(p).read()
def rep(a, b):
    global s
    assert a in s, a[:60]; s = s.replace(a, b)
rep("""    # The slate rules live in project-triage (slate.py, tested there). Absolute
    # interpreter path because launchd runs with a bare PATH.""",
    """    # The Front Burner date rules live in project-triage (frontburner.py, tested there).
    # Absolute interpreter path because launchd runs with a bare PATH.""")
rep("""    # Empty = the live registry next to portfolio.py. Tests pass a fixture.
    [string]$SlateRegistry = \"\"""",
    """    # Empty = the live registry next to portfolio.py. Tests pass a fixture.
    # (-SlateRegistry is the old name, kept so existing callers keep working.)
    [Alias("SlateRegistry")]
    [string]$Registry = \"\"""")
i = s.index("# --- slate: job-lane prioritization rules")
j = s.index("if ($Json) {", i)
block = r'''# --- Front Burner: every active project has a date --------------------------
# Replaces the retired slate check (project-triage plan 2026-10-31, Phase 4). The rules
# are evaluated in project-triage (`portfolio.py dates --json`, tested there); this only
# puts the verdict somewhere unavoidable. A check that FAILS must not read as OK - a
# silent pass is the invisible absence this script was written to catch.
$fbStatus = "DUE"
$fbWhy = ""
try {
    $fbArgs = @($PortfolioScript, "dates", "--json", "--today", $today.ToString('yyyy-MM-dd'))
    if ($Registry) { $fbArgs += @("--registry", $Registry) }
    $raw = & $Python @fbArgs 2>&1 | Out-String
    if ($LASTEXITCODE -ne 0) { throw "dates exited $LASTEXITCODE - $($raw.Trim())" }
    $ask = @(@($raw | ConvertFrom-Json) | Where-Object { $_.needs_eric })
    if ($ask.Count -eq 0) {
        $fbStatus = "OK"
        $fbWhy = "every active project has a date"
    } else {
        $fbStatus = if (@($ask | Where-Object { $_.kind -eq 'overdue' }).Count -gt 0) { "OVERDUE" } else { "DUE" }
        $fbWhy = (@($ask) | Select-Object -First 3 | ForEach-Object { "$($_.project): $($_.message)" }) -join " | "
    }
}
catch {
    $fbWhy = "front burner check could not run: $_"
}
# Friday: write Eric's weekly moves report into the vault. Both Friday runs
# (15:30 and 17:00) overwrite the same dated file, so the later one includes the
# afternoon's debrief. The folder keeps its old name (Inbox/weekly-slate).
if ($today.DayOfWeek -eq 'Friday') {
    try {
        $weekArgs = @($PortfolioScript, "week-report", "--end", $today.ToString('yyyy-MM-dd'),
                      "--out", (Join-Path $Vault "Inbox/weekly-slate"))
        if ($Registry) { $weekArgs += @("--registry", $Registry) }
        $wout = & $Python @weekArgs 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0) { throw "week-report exited $LASTEXITCODE - $($wout.Trim())" }
        $fbWhy += " | weekly report: Inbox/weekly-slate/$($today.ToString('yyyy-MM-dd')).md"
    }
    catch {
        if ($fbStatus -eq "OK") { $fbStatus = "DUE" }
        $fbWhy += " | weekly report could not be written: $_"
    }
}
